THOUGHT: I’ll test a minimal `_split_gcd` empty-input guard, which would make `split_surds` return `(1, 0, expr)` for non-surd sums. I want to see whether `_sqrt_match` and `_sqrtdenest1` then return unchanged without errors.

```bash
cd /testbed && python - <<'PY'
import importlib
from sympy import S, I, Pow, Rational, Add, sqrt
radsimp_mod = importlib.import_module('sympy.simplify.radsimp')
orig_split_gcd = radsimp_mod._split_gcd

def patched_split_gcd(*a):
    if not a:
        return S.One, [], []
    return orig_split_gcd(*a)

radsimp_mod._split_gcd = patched_split_gcd
# patch module-level function in split_surds globals? split_surds references _split_gcd global; reassign module attr is enough
from sympy.simplify.sqrtdenest import _sqrt_match, _sqrtdenest1

for p in (Add(S(4), S(3)*I, evaluate=False), S.One + sqrt(S(2)), S(3)+S(3)*sqrt(S(2))):
    print('\np:', repr(p))
    try:
        print('split_surds:', radsimp_mod.split_surds(p))
    except Exception as e:
        print('split_surds error:', type(e).__name__, e)
    try:
        print('_sqrt_match:', _sqrt_match(p))
    except Exception as e:
        print('_sqrt_match error:', type(e).__name__, e)

expr = Pow(Add(S(4), S(3)*I, evaluate=False), Rational(1,2), evaluate=False)
print('\nexpr:', expr)
try:
    print('_sqrtdenest1:', _sqrtdenest1(expr))
except Exception:
    import traceback; traceback.print_exc()

print('\nvalid sqrtdenest:', __import__('sympy.simplify.sqrtdenest', fromlist=['sqrtdenest']).sqrtdenest(sqrt(S(5) + S(2)*sqrt(S(6)))))
radsimp_mod._split_gcd = orig_split_gcd
PY
